path = Path(__file__).with_name('demo_reviews.csv')
with path.open('w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=['text', 'label']); writer.writeheader()
    for label, samples in categories.items():
        for text in samples: writer.writerow({'text': text, 'label': label})
print(f'Wrote {path} (synthetic hand-authored examples; not an evaluation dataset)')
